    # Dictionary to store the computed max sums
    memo = {}

    def f(n):
        # If the value is already computed, return it
        if n in memo:
            return memo[n]
        # Base case: if n is less than or equal to 1
        if n <= 1:
            return n
        # Compute the max sum and store it in memo
        else:
            result = max((f(n // 2) + f(n // 3) + f(n // 4) + f(n // 5)), n)
