def sumofFactors(n):
    # If the number is odd, it has no even factors
    if (n % 2 != 0):
        return 0

    # Initialize result
    res = 1

    # Iterate over 2 to n-1 to find all factors
    for i in range(2, n):
        # If i is a factor of n
        if n % i == 0:
            # If i is even, add it to the result
            if i % 2 == 0:
